export function settleRound(state){if(!['playing','deathRound'].includes(state.phase))return{ok:false,reason:'Round is not active.',state};if(state.pendingFalseTongue||state.pendingDesireSeeds?.length||state.pendingSilverGains?.length||state.pendingSilverPlacement||state.pendingStealFire||state.pendingBurningCity||state.pendingReflection||state.pendingFruit||state.pendingArmageddon||state.pendingTabernacle||state.pendingFarewell||state.pendingEffectDiscard||state.pendingRebuild||state.pendingDivision||state.pendingAftermath||state.pendingNarrow||state.pendingCup||state.pendingOverflow||state.pendingRope)return{ok:false,reason:'An effect choice is still resolving.',state};if(state.phase==='playing'&&state.players.filter(p=>p.hasNormalAction).length>1)return{ok:false,reason:'More than one player remains eligible.',state};return{ok:true,state:settleRoundMutable(clone(state))};}
export const playResource=(s,a)=>executeNormalAction(s,{...a,type:'playResource'});export const playMiracle=(s,a)=>executeNormalAction(s,{...a,type:'playMiracle'});export const redraw=(s,a)=>executeNormalAction(s,{...a,type:'redraw'});export const endParticipation=(s,a)=>executeNormalAction(s,{...a,type:'endParticipation'});export const endEmptyHand=(s,a)=>executeNormalAction(s,{...a,type:'endEmptyHand'});export function listCardLocations(state){return[...state.deck,...state.discardPile,...state.playedArea,...state.removedForRound,...state.players.flatMap(p=>p.hand),...state.players.flatMap(p=>p.effects)].filter(card=>!isDeathCard(card)).map(c=>c.instanceId);}
